  constructor(source) {
    this.chars = Array.from(source)
    this.i = 0
    this.line = 1
    this.column = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  atEnd() {
    return this.i >= this.chars.length
  }

  /** Reads one code point, keeping the line and column in step with it. */
  next() {
    const ch = this.chars[this.i]
    this.i += 1
    if (ch === '\n') {
      this.line += 1
      this.column = 1
    } else if (ch === '\t') {
      this.column += TAB_WIDTH - ((this.column - 1) % TAB_WIDTH)
    } else {
      this.column += 1
    }
    return ch
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  scan() {
    const tokens = []
    for (;;) {
      this.skipTrivia()
      if (this.atEnd()) return tokens
      tokens.push(this.token())
    }
  }

  skipTrivia() {
    for (;;) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        this.next()
        continue
      }
      if (ch === '/' && this.peek(1) === '/') {
        while (!this.atEnd() && this.peek() !== '\n') this.next()
        continue
      }
      if (ch === '/' && this.peek(1) === '*') {
        this.blockComment()
        continue
      }
      return
    }
  }

  blockComment() {
    const line = this.line
    const column = this.column
    let depth = 0
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated block comment')
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.next()
        this.next()
        depth += 1
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.next()
        this.next()
        depth -= 1
        if (depth === 0) return
        continue
      }
      this.next()
    }
  }

  token() {
    const line = this.line
    const column = this.column
    const ch = this.peek()

    if (ch === 'r' && this.peek(1) === '"') return this.rawString(line, column)
    if (isIdentStart(ch)) return this.identifier(line, column)
    if (isDigit(ch)) return this.number(line, column)
    if (ch === '"') return this.string(line, column)

    for (const op of PUNCT) {
      if (op.length === 2 && this.peek() === op[0] && this.peek(1) === op[1]) {
        this.next()
        this.next()
        return { line, column, kind: 'punct', text: op }
      }
    }
    for (const op of PUNCT) {
      if (op.length === 1 && ch === op) {
        this.next()
        return { line, column, kind: 'punct', text: op }
      }
    }
    this.fail(line, column, `unexpected character ${ch}`)
  }

  identifier(line, column) {
    let text = ''
    while (isIdentPart(this.peek())) text += this.next()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { line, column, kind, text }
  }

  /** Consumes the run of identifier characters that made a number invalid. */
  numberError(line, column, text) {
    let full = text
    while (isIdentPart(this.peek())) full += this.next()
    this.fail(line, column, `invalid number ${full}`)
  }

  /**
   * Reads digits of `radix`, allowing a single `_` between two of them.
   * Returns the text read and how many digits it held.
   */
  digitRun(radix) {
    let text = ''
    let digits = 0
