    if (this.peek() === '.' && isDigit(this.peek(1))) {
      text += this.next()
      text += this.digitRun(10).text
    }
    const marker = this.peek()
    if (marker === 'e' || marker === 'E') {
      const after = this.peek(1)
      const signed = after === '+' || after === '-'
      if (isDigit(after) || (signed && isDigit(this.peek(2)))) {
        text += this.next()
        if (signed) text += this.next()
        text += this.digitRun(10).text
      }
    }
    if (isIdentPart(this.peek())) this.numberError(line, column, text)
    return { line, column, kind: 'number', text }
  }

  rawString(line, column) {
    this.next()
    this.next()
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      const ch = this.next()
      if (ch === '"') return { line, column, kind: 'rawstring', text: value }
      value += ch
    }
  }

  string(line, column) {
    this.next()
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      if (this.peek() === '\n') this.fail(this.line, this.column, 'newline in string')
      if (this.peek() === '"') {
        this.next()
        return { line, column, kind: 'string', text: value }
      }
      if (this.peek() === '\\') {
        value += this.escape(line, column)
        continue
      }
      value += this.next()
    }
  }

  escape(stringLine, stringColumn) {
    const line = this.line
    const column = this.column
    this.next()
    if (this.atEnd()) this.fail(stringLine, stringColumn, 'unterminated string')
    const ch = this.next()
    const bad = () => this.fail(line, column, `invalid escape \\${ch}`)
    switch (ch) {
      case 'n': return '\n'
      case 't': return '\t'
      case 'r': return '\r'
      case '\\': return '\\'
      case '"': return '"'
      case '0': return '\0'
      case 'x': {
        const a = this.peek()
        const b = this.peek(1)
        if (!isHex(a) || !isHex(b)) bad()
        this.next()
        this.next()
        return String.fromCharCode(parseInt(a + b, 16))
      }
      case 'u': {
        if (this.peek() !== '{') bad()
        let digits = ''
        let offset = 1
        while (isHex(this.peek(offset))) {
          digits += this.peek(offset)
          offset += 1
        }
        if (digits.length === 0 || this.peek(offset) !== '}') bad()
        const value = parseInt(digits, 16)
        if (!(value <= 0x10ffff)) bad()
        for (let k = 0; k <= offset; k += 1) this.next()
        return String.fromCodePoint(value)
      }
      default:
        return bad()
    }
  }
}

export function scan(source) {
  return new Scanner(source).scan()
}

export const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
