const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

function isDigit(ch) {
  return ch >= '0' && ch <= '9'
}

function isHex(ch) {
  return ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
}

function isLetter(ch) {
  return ch !== undefined && ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'))
}

function isIdentStart(ch) {
  return ch === '_' || isLetter(ch)
}

function isIdentPart(ch) {
  return isIdentStart(ch) || (ch !== undefined && isDigit(ch))
}

function digitOfRadix(ch, radix) {
  if (ch === undefined) return false
  if (radix === 16) return isHex(ch)
  if (radix === 8) return ch >= '0' && ch <= '7'
  if (radix === 2) return ch === '0' || ch === '1'
  return isDigit(ch)
