  }

  rawString(line, column) {
    this.next()
    this.next()
    let value = ''
    for (;;) {
      if (this.atEnd()) this.fail(line, column, 'unterminated string')
      const ch = this.next()
      if (ch === '"') return { line, column, kind: 'rawstring', text: value }
