  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    return 2
  }

  let tokens
  try {
    tokens = scan(readStdin())
  } catch (error) {
    if (!(error instanceof ScanError)) throw error
    process.stderr.write(`error: ${error.line}:${error.column}: ${error.reason}\n`)
    return 2
  }

  let out = ''
  if (mode === 'tokens') {
    for (const token of tokens) out += `${token.line}:${token.column} ${token.kind} ${body(token)}\n`
  } else {
    for (const kind of KINDS) out += `${kind} ${tokens.filter((t) => t.kind === kind).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
  return 0
}

